fun p =>
  have K := 1 + ⌈2 ^ 19 * p.L * p.Δ / p.ε ^ 2⌉₊;
  have B := (2 ^ 18 * p.σ ^ 2 / (↑↑p.n ^ 2 * p.ε ^ 2)).toNNReal;
  have C := p.l + p.b * ↑(64 + (p.d + ↑p.n - 1) / ↑p.n * (8 + (↑p.n * (p.d + 1)).log2));
  8 * ↑K * (Finset.univ.sup p.h + (∑ i, p.h i) * B + 2 * C)

